import type {
  DotContext,
  DotFrame,
  DotMap,
  DotShape,
  Preset,
  Renderer,
  RendererOptions,
  ResolvedRendererOptions,
} from "./types";

export const DEFAULT_RENDERER_OPTIONS: ResolvedRendererOptions = {
  color: "currentColor",
  dotMap: null,
  dotScale: 1,
  fit: "square",
  glow: 0,
  padding: 0.06,
  paused: false,
  preset: "contour",
  reducedMotion: "auto",
  shape: "circle",
  size: 64,
  speed: 1,
  state: "thinking",
  weight: 1,
};

/** Light spring for the thinking ↔ crisp transition. Slightly under-damped. */
const STIFFNESS = 140;
const DAMPING = 20;
const MAX_TIMESTEP = 0.05;
/** Below this the lattice is subpixel haze. In device pixels: that is where dots resolve. */
const MIN_AUTO_CELL_DEVICE_PX = 2;

/** Dot diameter, in cells, whose area fills the cell — what full ink must reach to paint solid. */
const FULL_COVERAGE_DIAMETER = 2 / Math.sqrt(Math.PI);

/** Options whose change invalidates the cached per-dot contexts. */
const DERIVED_KEYS = ["dotMap", "fit", "padding", "size", "weight"] as const;
/** Options whose change invalidates the cached canvas geometry. */
const LAYOUT_KEYS = ["dotMap", "size", "fit", "padding", "dotScale"] as const;

/**
 * Paint a {@link DotMap} onto a canvas and animate it. One per canvas, updated
 * through {@link Renderer.update}: the clock lives here, so props never restart it.
 */
export function createRenderer(
  canvas: HTMLCanvasElement,
  initial: RendererOptions = {}
): Renderer {
  const context = canvas.getContext("2d");
  if (!context) {
    throw new Error("benday: could not acquire a 2D context");
  }
  const ctx = context;

  let opts: ResolvedRendererOptions = {
    ...DEFAULT_RENDERER_OPTIONS,
    ...strip(initial),
  };

  // Caches, rebuilt only when their inputs change.
  let dots: DotContext[] = [];
  let toneScales: number[] = [];
  let displayCols = 1;
  let displayRows = 1;
  let ink = "#000";
  let cssWidth = 0;
  let cssHeight = 0;
  let cell = 0;
  let originX = 0;
  let originY = 0;
  let baseRadius = 0;

  // Animation state, deliberately outliving update().
  let clock = 0;
  let settle = 1;
  let velocity = 0;
  let frameId = 0;
  let running = false;
  let lastFrame = 0;
  let paintable = true;
  let systemReducedMotion = prefersReducedMotion();

  const frame: DotFrame = { a: 1, dx: 0, dy: 0, s: 1 };

  function isReduced(): boolean {
    return opts.reducedMotion === "auto"
      ? systemReducedMotion
      : opts.reducedMotion;
  }

  function presetFn(): Preset {
    return typeof opts.preset === "function"
      ? opts.preset
      : PRESETS[opts.preset].fn;
  }

  function buildDerived(): void {
    const map = opts.dotMap;
    if (!map) {
      dots = [];
      toneScales = [];
      displayCols = 1;
      displayRows = 1;
      return;
    }

    const display = buildDisplayMap(map, opts);
    displayCols = display.cols;
    displayRows = display.rows;
    dots = display.dots.map((dot, i) => {
      const nx = dot.x * 2 - 1;
      const ny = dot.y * 2 - 1;
      return {
        angle: Math.atan2(ny, nx),
        cols: displayCols,
        d: dot.d,
        i,
        n: display.dots.length,
        nx,
        ny,
        r: Math.min(1, Math.hypot(nx, ny) / Math.SQRT2),
        rand: dotRandom(i),
        rows: displayRows,
        t: dot.t,
        v: dot.v,
        x: dot.x,
        y: dot.y,
      };
    });
    toneScales = display.dots.map((dot) =>
      toneScale(dot.v, dot.t, opts.weight)
    );
  }

  function buildLayout(): void {
    const map = opts.dotMap;
    const cols = map ? displayCols : 1;
    const rows = map ? displayRows : 1;

    cssWidth = opts.size;
    cssHeight =
      opts.fit === "natural" ? opts.size / safeAspect(map) : opts.size;

    const dpr = devicePixelRatioCapped();
    canvas.width = Math.round(cssWidth * dpr);
    canvas.height = Math.round(cssHeight * dpr);
    canvas.style.width = `${cssWidth}px`;
    canvas.style.height = `${cssHeight}px`;

    const padding = opticalPadding(opts.padding, Math.min(cssWidth, cssHeight));
    const availableWidth = cssWidth * (1 - padding * 2);
    const availableHeight = cssHeight * (1 - padding * 2);
    cell = Math.min(availableWidth / cols, availableHeight / rows);
    // A fine lattice lands every dot on a different fraction of a device pixel,
    // so each antialiases differently and the grid dissolves. Only small marks
    // need it, and only if the snapped lattice still fits the canvas.
    if (opticalFactor(Math.min(cssWidth, cssHeight)) > 0) {
      const devicePixel = 1 / dpr;
      const snapped = Math.max(
        devicePixel,
        Math.round(cell / devicePixel) * devicePixel
      );
      if (snapped * cols <= cssWidth && snapped * rows <= cssHeight) {
        cell = snapped;
      }
    }
    originX = snapTo((cssWidth - cell * cols) / 2, dpr);
    originY = snapTo((cssHeight - cell * rows) / 2, dpr);
    baseRadius = (cell * FULL_COVERAGE_DIAMETER * opts.dotScale) / 2;

    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  function buildInk(): void {
    ink = resolveInk(canvas, opts.color);
  }

  function paint(): void {
    ctx.clearRect(0, 0, cssWidth, cssHeight);
    if (dots.length === 0) {
      return;
    }

    ctx.fillStyle = ink;
    const optical = opticalFactor(Math.min(cssWidth, cssHeight));
    // Only `glow` blurs. Small marks used to get a halo here for optical
    // weight, but at 16px it came out wider than the cell and the lattice bled
    // into haze; `optical` buys that weight through radius and alpha instead.
    if (opts.glow > 0) {
      ctx.shadowColor = ink;
      ctx.shadowBlur = baseRadius * 4 * opts.glow;
    } else {
      ctx.shadowBlur = 0;
    }

    const run = presetFn();
    const cols = displayCols;
    const rows = displayRows;
    const motion = (1 - settle) * (1 - optical * 0.65);

    for (let i = 0; i < dots.length; i++) {
      const dot = dots[i] as DotContext;
      frame.s = 1;
      frame.a = 1;
      frame.dx = 0;
      frame.dy = 0;
      run(dot, clock, frame);

      // settle = 1 is the crisp logo; blend every channel toward it.
      const settledScale = frame.s + (1 - frame.s) * settle;
      const settledAlpha = frame.a + (1 - frame.a) * settle;
      const scale = settledScale + (1 - settledScale) * optical * 0.55;
      const alpha = settledAlpha + (1 - settledAlpha) * optical * 0.8;
      const radius =
        baseRadius * scale * (toneScales[i] as number) * shapeScale(opts.shape);
      if (radius <= 0.05) {
        continue;
      }
      const opacity = Math.min(1, Math.max(0, alpha));
      if (opacity <= 0.004) {
        continue;
      }

      ctx.globalAlpha = opacity;
      drawDot(
        ctx,
        opts.shape,
        originX + (dot.x * cols + frame.dx * motion) * cell,
        originY + (dot.y * rows + frame.dy * motion) * cell,
        radius
      );
    }

    ctx.globalAlpha = 1;
    ctx.shadowBlur = 0;
  }

  function settleTarget(): number {
    return opts.state === "thinking" ? 0 : 1;
  }

  function isSettled(): boolean {
    return settle === settleTarget() && velocity === 0;
  }

  function shouldAnimate(): boolean {
    if (isReduced() || opts.paused || !paintable) {
      return false;
    }
    return opts.state === "thinking" || !isSettled();
  }

  function step(now: number): void {
    const dt = lastFrame
      ? Math.min(MAX_TIMESTEP, (now - lastFrame) / 1000)
      : 1 / 60;
    lastFrame = now;
    clock += dt * opts.speed;

    const target = settleTarget();
    velocity += ((target - settle) * STIFFNESS - velocity * DAMPING) * dt;
    settle += velocity * dt;
    if (Math.abs(target - settle) < 0.001 && Math.abs(velocity) < 0.01) {
      settle = target;
      velocity = 0;
    }

    paint();

    if (running && shouldAnimate()) {
      frameId = requestAnimationFrame(step);
    } else {
      running = false;
    }
  }

  function start(): void {
    if (running) {
      return;
    }
    running = true;
    lastFrame = 0;
    frameId = requestAnimationFrame(step);
  }

  function stop(): void {
    running = false;
    cancelAnimationFrame(frameId);
  }

  function sync(): void {
    if (shouldAnimate()) {
      start();
    } else {
      stop();
    }
  }

  // Reduced motion means "show me the mark, not the animation".
  function applyReducedMotion(): void {
    if (isReduced()) {
      settle = 1;
      velocity = 0;
    }
  }

  const stopTheme = watchTheme(() => {
    buildInk();
    if (!running) {
      paint();
    }
  });

  const stopReducedMotion = watchReducedMotion((reduced) => {
    systemReducedMotion = reduced;
    applyReducedMotion();
    paint();
    sync();
  });

  const stopPaintability = watchPaintability(canvas, (next) => {
    paintable = next;
    sync();
  });

  buildDerived();
  buildLayout();
  buildInk();
  applyReducedMotion();
  paint();
  sync();

  return {
    destroy(): void {
      stop();
      stopTheme();
      stopReducedMotion();
      stopPaintability();
    },

    get height(): number {
      return cssHeight;
    },

    get options(): Readonly<ResolvedRendererOptions> {
      return opts;
    },

    update(next: RendererOptions): void {
      const previous = opts;
      opts = { ...opts, ...strip(next) };

      if (DERIVED_KEYS.some((key) => previous[key] !== opts[key])) {
        buildDerived();
      }
      if (LAYOUT_KEYS.some((key) => previous[key] !== opts[key])) {
        buildLayout();
      }
      if (previous.color !== opts.color) {
        buildInk();
      }
      applyReducedMotion();

      paint();
      sync();
    },
  };
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

/** Round a CSS-pixel position onto the backing store's pixel grid. */
function snapTo(value: number, dpr: number): number {
  return Math.round(value * dpr) / dpr;
}

function clamp01(value: number): number {
  return clamp(value, 0, 1);
}

interface DisplayDot {
  d: number;
  t: number;
  v: number;
  x: number;
  y: number;
}

interface DisplayMap {
  cols: number;
  dots: DisplayDot[];
  rows: number;
}

/**
 * Downsample an over-dense map into a coarser regular lattice. Missing source
 * dots count as empty cells, so the aggregate retains the source's ink mass
 * instead of merely making every surviving dot larger.
 */
function buildDisplayMap(
  map: DotMap,
  opts: ResolvedRendererOptions
): DisplayMap {
  const sourceCols = Math.max(1, Math.round(map.cols));
  const sourceRows = Math.max(1, Math.round(map.rows));
  const source = { cols: sourceCols, dots: map.dots, rows: sourceRows };
  if (map.dots.length === 0) {
    return source;
  }

  const width = Math.max(1, opts.size);
  const height = opts.fit === "natural" ? width / safeAspect(map) : width;
  const padding = opticalPadding(opts.padding, Math.min(width, height));
  const cell = Math.min(
    (width * (1 - padding * 2)) / sourceCols,
    (height * (1 - padding * 2)) / sourceRows
  );
  const minCell = MIN_AUTO_CELL_DEVICE_PX / devicePixelRatioCapped();
  if (!Number.isFinite(cell) || cell >= minCell) {
    return source;
  }

  const scale = cell / minCell;
  const cols = Math.max(1, Math.floor(sourceCols * scale));
  const rows = Math.max(1, Math.floor(sourceRows * scale));
  if (cols === sourceCols && rows === sourceRows) {
    return source;
  }

  const bins = Array.from({ length: cols * rows }, () => ({
    depth: 0,
    ink: 0,
    tone: 0,
  }));
  for (const dot of map.dots) {
    const sourceCol = clamp(Math.floor(dot.col), 0, sourceCols - 1);
    const sourceRow = clamp(Math.floor(dot.row), 0, sourceRows - 1);
    const col = Math.min(cols - 1, Math.floor((sourceCol * cols) / sourceCols));
    const row = Math.min(rows - 1, Math.floor((sourceRow * rows) / sourceRows));
    const bin = bins[row * cols + col];
    if (!bin) {
      continue;
    }
    const coverage = clamp01(dot.v);
    bin.ink += coverage;
    bin.depth += clamp01(dot.d) * coverage;
    bin.tone += clamp01(dot.t) * coverage;
  }

  const dots: DisplayDot[] = [];
  for (let row = 0; row < rows; row++) {
    const sourceRowStart = Math.ceil((row * sourceRows) / rows);
    const sourceRowEnd = Math.ceil(((row + 1) * sourceRows) / rows);
    for (let col = 0; col < cols; col++) {
      const bin = bins[row * cols + col];
      if (!bin || bin.ink <= 0) {
        continue;
      }
      const sourceColStart = Math.ceil((col * sourceCols) / cols);
      const sourceColEnd = Math.ceil(((col + 1) * sourceCols) / cols);
      const sourceCells = Math.max(
        1,
        (sourceColEnd - sourceColStart) * (sourceRowEnd - sourceRowStart)
      );
      const coverage = clamp01(bin.ink / sourceCells);
      if (coverage <= 0.004) {
        continue;
      }
      dots.push({
        d: bin.depth / bin.ink,
        t: bin.tone / bin.ink,
        v: coverage,
        x: (col + 0.5) / cols,
        y: (row + 0.5) / rows,
      });
    }
  }

  return { cols, dots, rows };
}

/**
 * A halftone represents coverage through area: radius therefore follows the
 * square root of tone. Opacity remains available to the animation instead of
 * applying coverage twice (radius, then alpha), which used to erase fine ink.
 *
 * Tone is what the cell covers times how dark it is. The floors this used to
 * multiply in compounded: empty cells painted 0.169 and full ones 0.319, so
 * every logo arrived the same flat grey. Depth stays out — it is the animation
 * channel, and folding it in only pulls area off the artwork's own tones.
 */
function toneScale(
  coverage: number,
  sourceTone: number,
  weight: number
): number {
  const w = clamp01(weight);
  // Below 1, weight interpolates toward a uniform field rather than shifting a floor.
  const weighted = 1 - w + w * clamp01(coverage);
  return Math.sqrt(clamp01(weighted * clamp01(sourceTone)));
}

/** Small marks need optical weight and restrained motion to remain identifiable. */
function opticalFactor(size: number): number {
  return clamp01((32 - size) / 16);
}

function opticalPadding(padding: number, size: number): number {
  return clamp(padding, 0, 0.49) * (1 - opticalFactor(size) * 0.65);
}

/** Keep circle, square and diamond at equal painted area for the same tone. */
function shapeScale(shape: DotShape): number {
  if (shape === "square") {
    return Math.sqrt(Math.PI / 4);
  }
  if (shape === "diamond") {
    return Math.sqrt(Math.PI / 2);
  }
  return 1;
}

function safeAspect(map: DotMap | null): number {
  if (map && Number.isFinite(map.aspect) && map.aspect > 0) {
    return map.aspect;
  }
  return map ? map.cols / Math.max(1, map.rows) : 1;
}

function drawDot(
  ctx: CanvasRenderingContext2D,
  shape: DotShape,
  x: number,
  y: number,
  r: number
): void {
  if (shape === "circle") {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
    return;
  }
  if (shape === "square") {
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
    return;
  }
  ctx.beginPath();
  ctx.moveTo(x, y - r);
  ctx.lineTo(x + r, y);
  ctx.lineTo(x, y + r);
  ctx.lineTo(x - r, y);
  ctx.closePath();
  ctx.fill();
}

/** Drop explicit `undefined` so spreading options never clobbers a default. */
function strip(options: RendererOptions): RendererOptions {
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(options)) {
    if (value !== undefined) {
      out[key] = value;
    }
  }
  return out as RendererOptions;
}

/** A single dot sampled out of the source image. */
export interface Dot {
  /** Grid column. */
  col: number;
  /** Grid row. */
  row: number;
  /** Cell-center x, normalized 0..1 across the trimmed content box. */
  x: number;
  /** Cell-center y, normalized 0..1 across the trimmed content box. */
  y: number;
  /** Ink coverage of the cell, 0..1 (post-gamma). Drives the dot's painted area. */
  v: number;
  /** Source tone, 0 for the weakest layer and 1 for the strongest layer. */
  t: number;
  /** Depth inside the shape, 0 at the outline → 1 at the thickest point (from the EDT). */
  d: number;
}

/**
 * A baked logo: dots plus the geometry to lay them out. All the renderer needs,
 * small and JSON-serializable, so it can be produced at build time.
 */
export interface DotMap {
  /** Grid columns across the trimmed content box. */
  cols: number;
  /** Grid rows across the trimmed content box. */
  rows: number;
  /** width / height of the trimmed content box. */
  aspect: number;
  /** The dots that cleared the coverage threshold. */
  dots: Dot[];
  /** How many grid cells were tested (cols * rows) — useful for tuning feedback. */
  cells: number;
  /** Which masking strategy actually ran. */
  maskMode: "alpha" | "luma";
}

export type MaskMode = "auto" | "alpha" | "luma";

export interface BakeOptions {
  /** Dots across the longest side of the trimmed logo. @default 24 */
  grid?: number;
  /** Cell coverage required to emit a dot, 0..1. @default 0.18 */
  threshold?: number;
  /** Gamma applied to coverage before thresholding. <1 boosts faint ink. @default 1 */
  gamma?: number;
  /** How to separate ink from background; `auto` picks alpha over luma. @default 'auto' */
  maskMode?: MaskMode;
  /** Treat the luminance mask as inverted (light ink on dark). Only used in luma mode. */
  invert?: boolean;
  /** Grow the mask by N working pixels — the hairline rescue knob. @default 0 */
  dilate?: number;
  /** Trim to the mask's bounding box before gridding. @default true */
  trim?: boolean;
  /** Resolution the mask is computed at, longest side. @default auto from grid */
  workingSize?: number;
}

export type ResolvedBakeOptions = Required<Omit<BakeOptions, "workingSize">> & {
  workingSize: number;
};

/** Per-dot input handed to an animation preset each frame. */
export interface DotContext {
  /** Index in the dot list. */
  i: number;
  /** Total dot count. */
  n: number;
  /** Normalized position, 0..1. */
  x: number;
  y: number;
  /** Normalized position relative to the mark's center, roughly -1..1. */
  nx: number;
  ny: number;
  /** Radial distance from center, normalized so the corner is ~1. */
  r: number;
  /** Angle from center, -PI..PI. */
  angle: number;
  /** Ink coverage, 0..1. */
  v: number;
  /** Source tone, 0..1. */
  t: number;
  /** Depth inside the shape, 0 at the outline → 1 at the core. */
  d: number;
  /** Stable pseudo-random value for this dot, 0..1. */
  rand: number;
  /** Grid dimensions, so offsets can be reasoned about in cell units. */
  cols: number;
  rows: number;
}

/** What a preset produces for one dot on one frame. */
export interface DotFrame {
  /** Radius multiplier. */
  s: number;
  /** Alpha, 0..1. */
  a: number;
  /** Offset in cell units (1 = one grid cell). */
  dx: number;
  dy: number;
}

export type Preset = (c: DotContext, t: number, out: DotFrame) => void;

export type PresetName =
  | "shimmer"
  | "ripple"
  | "contour"
  | "scatter"
  | "flicker"
  | "breathe"
  | "swirl"
  | "scan"
  | "cascade"
  | "orbit"
  | "comet"
  | "radar"
  | "pinwheel"
  | "wave"
  | "equalizer"
  | "weave"
  | "beacon"
  | "glitch"
  | "rain"
  | "magnetic"
  | "resolve";

export type BendayState = "idle" | "thinking" | "done";

export type DotShape = "circle" | "square" | "diamond";

export type Fit = "square" | "natural";

/** Everything the renderer needs to paint a frame. */
export interface RendererOptions {
  /** The baked map to draw. `null` paints nothing. */
  dotMap?: DotMap | null;
  /** Preset name, or your own per-dot function. @default 'contour' */
  preset?: PresetName | Preset;
  /** @default 'thinking' */
  state?: BendayState;
  /** Rendered size in CSS pixels. @default 64 */
  size?: number;
  /** `natural` sizes the canvas to the mark's aspect, which wordmarks need. @default 'square' */
  fit?: Fit;
  /** Animation speed multiplier. @default 1 */
  speed?: number;
  /** Dot color. `currentColor` resolves against the canvas. @default 'currentColor' */
  color?: string;
  /** Dot size against a full-coverage halftone dot; 1 lets solid ink paint solid. @default 1 */
  dotScale?: number;
  /** @default 'circle' */
  shape?: DotShape;
  /** Glow radius as a fraction of the dot size, 0 disables. @default 0 */
  glow?: number;
  /** Inset around the mark as a fraction of the box. @default 0.06 */
  padding?: number;
  /** How strongly ink coverage drives each dot's painted area, 0..1. @default 1 */
  weight?: number;
  /** Freeze on the current frame. @default false */
  paused?: boolean;
  /** `auto` follows prefers-reduced-motion live; a boolean pins it. @default 'auto' */
  reducedMotion?: boolean | "auto";
}

export type ResolvedRendererOptions = Required<
  Omit<RendererOptions, "dotMap">
> & {
  dotMap: DotMap | null;
};

/**
 * A live canvas painter. Update it rather than recreating it, so the clock and
 * the settle spring survive prop changes.
 */
export interface Renderer {
  /** Merge new options in and repaint. Unspecified keys keep their value. */
  update: (next: RendererOptions) => void;
  /** The currently applied options. */
  readonly options: Readonly<ResolvedRendererOptions>;
  /** Canvas CSS height for the current options. */
  readonly height: number;
  /** Tear down observers and cancel any pending frame. */
  destroy: () => void;
}

"use client";

import { useEffect, useRef, useState } from "react";

import type { BakeSource } from "./bake";
import { bake, bakeCached } from "./bake";
import type { BakeOptions, DotMap } from "./types";

export interface UseDotMapResult {
  dotMap: DotMap | null;
  loading: boolean;
  error: Error | null;
  /** Milliseconds the last bake took — handy for tuning. */
  elapsed: number | null;
}

const IDLE: UseDotMapResult = {
  dotMap: null,
  elapsed: null,
  error: null,
  loading: false,
};

const LOADING: UseDotMapResult = { ...IDLE, loading: true };

/**
 * Bake a source into a {@link DotMap}, re-running on change. Strings hit the
 * module cache; Blobs and Files bake fresh, having no stable identity.
 */
export function useDotMap(
  source: BakeSource | null | undefined,
  options: BakeOptions = {}
): UseDotMapResult {
  const optionsKey = JSON.stringify(options);

  // A string plus its options determines the result, so the pair keys the
  // effect. Anything else falls back to reference identity.
  const signature =
    typeof source === "string" ? `${source}|${optionsKey}` : source;

  const optionsRef = useRef<BakeOptions>(options);
  useEffect(() => {
    optionsRef.current = options;
  });

  const [state, setState] = useState<UseDotMapResult>(source ? LOADING : IDLE);
  // Reset to a loading frame *during* render when the input changes, rather
  // than in an effect — an effect would paint one frame of stale results first.
  const [lastSignature, setLastSignature] = useState(signature);
  if (signature !== lastSignature) {
    setLastSignature(signature);
    setState(source ? LOADING : IDLE);
  }

  useEffect(() => {
    if (!source) {
      return;
    }

    let live = true;
    const started = performance.now();

    const run = async () => {
      try {
        const dotMap =
          typeof source === "string"
            ? await bakeCached(source, optionsRef.current)
            : await bake(source, optionsRef.current);
        if (live) {
          setState({
            dotMap,
            elapsed: performance.now() - started,
            error: null,
            loading: false,
          });
        }
      } catch (error) {
        if (live) {
          setState({
            dotMap: null,
            elapsed: null,
            error: error as Error,
            loading: false,
          });
        }
      }
    };

    run();

    return () => {
      live = false;
    };
  }, [signature, source]);

  return state;
}
